const NOW = Date.now();
const cfg = (($('Config ophalen').all()[0]||{}).json)||{};
const TH  = (cfg.thresholds && cfg.thresholds.default) || {};
const OFFLINE_MIN = TH.offline_min ?? 10, UPD_MANY = TH.updates_many ?? 20;
const BAT_MIN = TH.bat_min ?? 15, DISK_WARN = TH.disk_warn ?? 80, DISK_ALARM = TH.disk_alarm ?? 90;
const TEMP_ALARM = TH.temp_alarm ?? 90;
const num = v => (v==null||v==='')?NaN:Number(v);
const tms = r => Date.parse(r.ts);
const hhmm = () => new Date(NOW).toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Amsterdam'});
const asArr = v => Array.isArray(v)?v:(typeof v==='string'?(()=>{try{return JSON.parse(v)}catch(e){return null}})():null);
const rows = $input.all().map(i=>i.json);          // v_latest: 1 rij per machine
const online = rows.filter(r=>!isNaN(tms(r)) && (NOW-tms(r))/60000 <= OFFLINE_MIN);
const label = m => (m||'?');

const t=hhmm(); const store=$getWorkflowStaticData('global'); store.u=store.u||{};
const out=[];
for(const d of online){
  const m=label(d.machine); const upd=num(d.updates); if(isNaN(upd)) continue;
  const cat = upd<=0?'uptodate':(upd>UPD_MANY?'many':'some');
  const prev = store.u[m];
  if(prev===undefined){ store.u[m]=cat; continue; }   // eerste run: stil onthouden
  if(cat!==prev){ store.u[m]=cat;
    if(cat==='uptodate'){
      out.push({json:{caption:'\u2713 Up-to-date \u2014 '+m,
        spec:{title:'\u2713 Alles bijgewerkt \u2014 '+m,subtitle:t,state:'ok',
          rows:[{label:'UPDATES',value:'up-to-date',status:'ok'}],footer:'SysDash \u00b7 updates \u00b7 '+t}}});
    } else {
      const sym = cat==='many'?'\u26A0':'\u25CF'; const st = cat==='many'?'high':'warn';
      out.push({json:{caption:sym+' Updates \u2014 '+m+' \u00b7 '+upd+' klaar',
        spec:{title:sym+' Updates beschikbaar \u2014 '+m,subtitle:t,state: cat==='many'?'alert':'ok',
          rows:[{label:'UPDATES',value:upd+' klaar',status:st}],footer:'SysDash \u00b7 updates \u00b7 '+t}}});
    }
  }
}
return out;
